{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_22",
      "quote": "Potential limitations of this systematic review stem from current limitations of prognosis literature. Firstly, although the discriminatory performance of prognostic models can be quantitatively assessed by pooling the reported c statistics in each study, the methods used to assess the calibration of each model vary substantially. Given the limitations of statistical measures of calibration, including observed to expected ratios and Hosmer-­Lemeshow χ2 tests, 18 19 we only assessed calibration through the studies' reported calibration plots. ... Secondly, the included studies assessed model calibration among patients with relatively low cardiovascular risk, limiting assessment of model calibration across the full spectrum of risk including among those with established cardiovascular disease or chronic kidney disease. ... Thirdly, we were unable to assess on the predictive model performance the influence of several potential sources of heterogeneity, including ascertainment of outcomes across studies, the time periods in which they were conducted and available antidiabetic treatments available during these periods, and diversities in healthcare systems and health outcomes across geographical regions.",
      "reason": "The manuscript explicitly describes the current state of knowledge about prognostic model performance and lists important uncertainties and limitations (calibration methods, limited risk spectrum, heterogeneity across studies)."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_1",
      "quote": "OBJECTIVE To summarise available evidence regarding the performance metrics of validated prognostic models on cardiovascular and kidney outcomes in adults with type 2 diabetes mellitus. DESIGN Living systematic review and meta-­analysis",
      "reason": "The abstract states the objective to summarise evidence about prognostic model performance, providing the importance and need for the review (to synthesise evidence on model performance for key outcomes in type 2 diabetes)."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PARTIAL",
      "chunk_id": "text_21",
      "quote": "Strengths of this review include the use of rigorous and comprehensive methods for systematic reviews and meta-­analyses of prognostic models 10 11 and the use of formal GRADE guidance to assess certainty of evidence for discrimination and calibration. 18 20 The GRADE approach allowed us to contextualise our findings in relation to the average discriminatory performance of clinicians, enabling our findings to have direct relevance to clinical practice. Furthermore, this updated review continues to be linked to a multidisciplinary BMJ Rapid Recommendation panel composed of clinical experts, methodologists, and patient partners.",
      "reason": "The text indicates this is an \"updated review\" and references methodological advances and linkage to guidelines, implying a rationale relative to prior work; however it does not explicitly describe the need for the current review relative to specific prior similar systematic reviews nor does it clearly cite and explain how this review updates or differs from previous reviews beyond being \"updated.\""
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review addresses prognostic model performance for outcomes in type 2 diabetes (not effects of interventions). The abstract and objectives describe prognostic models rather than interventions (see text_1), so describing a mechanism of action of an intervention does not apply."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review concerns prognostic model performance rather than evaluation of complex interventions or delivery contexts; therefore a logic model of intervention components and outcomes is not applicable. The scope focused on validation and performance of prognostic models (see text_1)."
    }
  ],
  "confidence": 85
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PARTIAL",
      "chunk_id": "text_1",
      "quote": "OBJECTIVE To summarise available evidence regarding the performance metrics of validated prognostic models on cardiovascular and kidney outcomes in adults with type 2 diabetes mellitus.",
      "reason": "The review objective is explicitly stated (summarising evidence on prognostic model performance for cardiovascular and kidney outcomes in adults with type 2 diabetes). However, it is not framed using a recognized question-formulation framework (e.g., PICO or similar); it is a clear objective but not presented in a question-framework format."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_1",
      "quote": "OBJECTIVE To summarise available evidence regarding the performance metrics of validated prognostic models on cardiovascular and kidney outcomes in adults with type 2 diabetes mellitus.",
      "reason": "This review addresses prognostic model performance, not intervention effects; the conditional requirement about planned comparisons using PICO applies only to intervention-effect reviews and therefore does not apply here."
    }
  ],
  "confidence": 85
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_2",
      "quote": "STUDIES Studies validating prognostic models that predicted all cause and cardiovascular mortality, admission to hospital for heart failure, kidney failure, myocardial infarction, or ischaemic stroke in adults with type 2 diabetes mellitus, including people with established cardiovascular disease or chronic kidney disease, or both. Risk models evaluating composite outcomes were not eligible.",
      "reason": "The manuscript reports the target population (adults with type 2 diabetes, including those with CVD or CKD) and specifies eligible outcomes and exclusion of composite outcomes, but does not explicitly specify eligible study designs, settings, or follow-up requirements in the provided evidence."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No information in the retrieved evidence specifies eligibility criteria for report characteristics (dissemination year, language, or publication/report status)."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The retrieved evidence does not report whether the review distinguished exclusion because outcomes were not measured from exclusion because outcome results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "DATA SYNTHESIS For each model and outcome, using a random effects model, the reported discrimination measures were pooled, reported as c statistics.",
      "reason": "The review specifies how studies were grouped for synthesis—by individual model and outcome—and describes the pooling approach (random effects pooling of reported discrimination measures), linking groups to the comparisons (models vs outcomes)."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_22",
      "quote": "Fourthly, our review excluded prognostic models solely evaluating composite outcomes, such as major adverse cardiovascular events, as our linked guideline focused on individual cardiovascular and kidney outcomes. As a result, several robust risk prediction models for type 2 diabetes mellitus, such as SCORE2- Diabetes, 15 which may assist clinicians and patients with risk stratification in clinical practice, were not assessed in our review.",
      "reason": "The manuscript provides a rationale for a notable restriction (exclusion of models evaluating composite outcomes) tied to the linked guideline's focus on individual cardiovascular and kidney outcomes."
    }
  ],
  "confidence": 85
}

